TEST(testBSONDecodeNeverThrows) {
	// The public contract is bool + lastError, so no exception may escape
	// fromBSON() -- not asvJSONError and not std::bad_alloc/std::length_error
	// raised by an oversized length prefix.
	asvJSON json;
	// Oversized string length prefix (0x7FFFFFFF) with a truncated payload.
	{
		uint8_t data[] = {
			0x0F, 0x00, 0x00, 0x00, // document length = 15
			0x02, 's', 0x00,        // element type 0x02 (string), key "s"
			0xFF, 0xFF, 0xFF, 0x7F, // string length = 0x7FFFFFFF
			0x00, 0x00, 0x00,       // truncated payload
			0x00                    // document terminator
		};
		bool threw = false;
		try { json.fromBSON(data, sizeof(data)); } catch (...) { threw = true; }
		ASSERT(!threw);
		ASSERT(!json.getLastError().empty());
		ASSERT(json.getRoot() == nullptr);
	}
	// Oversized binary length prefix.
	{
		uint8_t data[] = {
			0x0F, 0x00, 0x00, 0x00,
			0x05, 'b', 0x00,        // element type 0x05 (binary), key "b"
			0xFF, 0xFF, 0xFF, 0x7F, // binary length = 0x7FFFFFFF
			0x00, 0x00, 0x00,
			0x00
		};
		bool threw = false;
		try { json.fromBSON(data, sizeof(data)); } catch (...) { threw = true; }
		ASSERT(!threw);
	}
	// Unknown element type and a bogus document length.
	{
		uint8_t d1[] = {0x08, 0x00, 0x00, 0x00, 0x08, 'a', 0x00, 0x00};
		bool threw = false;
		try { json.fromBSON(d1, sizeof(d1)); } catch (...) { threw = true; }
		ASSERT(!threw);
	}
	{
		uint8_t d2[] = {0xFF, 0xFF, 0xFF, 0xFF, 0x00};
		bool threw = false;
		try { json.fromBSON(d2, sizeof(d2)); } catch (...) { threw = true; }
		ASSERT(!threw);
	}
}

TEST(testBSONDecimal128) {
	// BSON decimal128 (element type 0x13) is rejected rather than silently
	// replaced with null, which would lose data.
	uint8_t data[] = {
		0x18, 0x00, 0x00, 0x00, // int32 length = 24
		0x13, 'd', 0x00,        // type decimal128, key "d"
		0x00,0x00,0x00,0x00,0x00,0x00,0x00,0x00,0x00,0x00,0x00,0x00,0x00,0x00,0x00,0x00,
		0x00                    // document terminator
	};
	asvJSON json;
	bool ok = json.fromBSON(data, sizeof(data));
	if (ok) throw std::runtime_error("decimal128 should fail");
	ASSERT(!json.getLastError().empty());
	// A TRUNCATED decimal128 payload reports the same rejection, not a crash:
	// the parser deliberately never advanced the cursor over the 16 bytes, so
	// there is nothing left to be read after the throw.
	{
		uint8_t trunc[] = {
			0x0F, 0x00, 0x00, 0x00, // document length = 15
			0x13, 'd', 0x00,        // type decimal128, key "d"
			0x00, 0x00, 0x00,       // only 3 of 16 payload bytes present
			0x00                    // document terminator
		};
		asvJSON j2;
		bool threw = false;
		bool ok2 = true;
		try { ok2 = j2.fromBSON(trunc, sizeof(trunc)); } catch (...) { threw = true; }
		ASSERT(!threw);
		ASSERT(!ok2);
		ASSERT(!j2.getLastError().empty());
	}
}

TEST(testMessagePackCorruptedData) {
	asvJSON json;
	// null/empty data
	bool ok = json.fromMessagePack(nullptr, 0);
	if (ok) throw std::runtime_error("null data should fail");

	// Truncated array header
	{
		uint8_t data[] = {0x93}; // array of 3, but no elements
		asvJSON json2;
		ok = json2.fromMessagePack(data, sizeof(data));
		if (ok) throw std::runtime_error("truncated array should fail");
		ASSERT(!json2.getLastError().empty());
	}

	// Truncated map header
	{
		uint8_t data[] = {0x81}; // map of 1, but no key/value
		asvJSON json2;
		ok = json2.fromMessagePack(data, sizeof(data));
		if (ok) throw std::runtime_error("truncated map should fail");
		ASSERT(!json2.getLastError().empty());
	}

	// Truncated string
	{
		uint8_t data[] = {0xa5, 'h', 'e', 'l'}; // str5 but only 3 bytes
		asvJSON json2;
		ok = json2.fromMessagePack(data, sizeof(data));
		if (ok) throw std::runtime_error("truncated string should fail");
		ASSERT(!json2.getLastError().empty());
	}

	// Truncated fixext4 (0xD6 needs 5 bytes: 1 type + 4 data)
	{
		uint8_t data[] = {0xD6, 0x01, 0x02}; // fixext4 but only 2 data bytes instead of 4
		asvJSON json2;
		ok = json2.fromMessagePack(data, sizeof(data));
		if (ok) throw std::runtime_error("truncated fixext4 should fail");
		ASSERT(!json2.getLastError().empty());
	}

	// Trailing bytes after valid value
	{
		uint8_t data[] = {0x01, 0x02}; // valid int 1, trailing byte 2
		asvJSON json2;
		ok = json2.fromMessagePack(data, sizeof(data));
		if (ok) throw std::runtime_error("trailing bytes should fail");
	}

	// Truncated bin8
	{
		uint8_t data[] = {0xc4, 0x05, 0x01, 0x02}; // bin8 len=5, only 2 bytes
		asvJSON json2;
		ok = json2.fromMessagePack(data, sizeof(data));
		if (ok) throw std::runtime_error("truncated bin8 should fail");
	}
}

TEST(testMessagePackInvalidUTF8) {
	// fixstr (0xA5) with invalid UTF-8 continuation byte 0x80.
	{
		uint8_t data[] = {0xa3, 0xC0, 0x80, 'X'}; // str3 but first byte is overlong
		asvJSON json2;
		bool ok = json2.fromMessagePack(data, sizeof(data));
		if (ok) throw std::runtime_error("invalid UTF-8 fixstr should fail");
	}
	// str8 with invalid standalone 0xFE.
	{
		uint8_t data[] = {0xd9, 0x02, 0xFE, 0xFF};
		asvJSON json2;
		bool ok = json2.fromMessagePack(data, sizeof(data));
		if (ok) throw std::runtime_error("invalid UTF-8 str8 should fail");
	}
	// str16 with invalid continuation.
	{
		uint8_t data[] = {0xda, 0x00, 0x03, 'A', 0x80, 'B'};
		asvJSON json2;
		bool ok = json2.fromMessagePack(data, sizeof(data));
		if (ok) throw std::runtime_error("invalid UTF-8 str16 should fail");
	}
	// str32 with invalid standalone 0xF0.
	{
		uint8_t data[] = {0xdb, 0x00, 0x00, 0x00, 0x02, 0xF0, 'X'};
		asvJSON json2;
		bool ok = json2.fromMessagePack(data, sizeof(data));
		if (ok) throw std::runtime_error("invalid UTF-8 str32 should fail");
	}
	// Valid multi-byte UTF-8 must still parse fine.
	{
		const char* utf8 = "\xd0\xbf\xd1\x80\xd0\xb8\xd0\xb2\xd0\xb5\xd1\x82"; // "privet"
		std::vector<uint8_t> data = {0xac};
		data.insert(data.end(), (uint8_t*)utf8, (uint8_t*)utf8 + 12);
		asvJSON json2;
		bool ok = json2.fromMessagePack(data.data(), data.size());
		if (!ok) throw std::runtime_error("valid UTF-8 fixstr should succeed");
		std::string_view sv = json2.getRoot()->getString();
		if (sv != "\xd0\xbf\xd1\x80\xd0\xb8\xd0\xb2\xd0\xb5\xd1\x82") throw std::runtime_error("UTF-8 value mismatch");
	}
}

TEST(testMsgPackUInt64Overflow) {
	// uint64 (0xCF) value above int64 max (0xFFFFFFFFFFFFFFFF)
	// must be rejected before makeInt() (which performs no range check).
	std::vector<uint8_t> data = { 0xCF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF };
	asvJSON json;
	bool ok = json.fromMessagePack(data.data(), data.size());
	if (ok) throw std::runtime_error("fromMessagePack accepted uint64 above int64 max");
	ASSERT(!json.getLastError().empty());

	// Boundary: 0x7FFFFFFFFFFFFFFF must still parse as INT64_MAX.
	std::vector<uint8_t> maxData = { 0xCF, 0x7F, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF };
	asvJSON json2;
	if (!json2.fromMessagePack(maxData.data(), maxData.size())) throw std::runtime_error("fromMessagePack rejected int64 max");
	ASSERT_EQ(json2.getRoot()->getInt(), INT64_MAX);
}

TEST(testDuplicateKeyNoLeak) {
	asvJSON json;
	json.parse(std::string("{\"a\": 1}"));
	json.putInt("a", 2);
	json.putInt("a", 3);
	if (json.getInt("a") != 3) throw std::runtime_error("overwrite failed");
	auto* root = json.getRoot();
	if (!root || root->size() != 1) throw std::runtime_error("duplicate key leak");
}

