		json.putRegex("rx", "^test$", "gi");
		uint8_t bin[] = {0xde, 0xad};
		json.putBinary("bin", bin, 2);
		uint8_t ext[] = {0x01, 0x02};
		json.putExtension("ext", 42, ext, 2);
