		ASSERT(out.find("# tail") != std::string::npos);
		asvJSON j2;
		ASSERT(j2.fromYAML(out));
		asvJSONValue* lst = j2.getRoot()->get("list");
		ASSERT(lst != nullptr && lst->type == asvJSONValue::ARRAY);
