		asvJSON json;
		ASSERT(json.fromYAML("- &x !!map\n  k: 1\n- *x"));
		auto* it = json.getRoot()->arr->at(1).get();
		ASSERT(it != nullptr && it->type == asvJSONValue::OBJECT);
		ASSERT_EQ(it->get("k")->getInt(), 1);
